class Solution {
public:
    vector<int> solve(vector<int>& nums, vector<vector<int>>& queries) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            long s = 0;
            for (int j = q[0]; j < n; j += q[1]) s += nums[j];
            ans.push_back((int)(s % MOD));
        }
        return ans;
    }
};

