public:
    vector<int> solve(vector<int>& nums, vector<vector<int>>& queries) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        int b = (int)sqrt(n) + 1;
        vector<vector<int>> dp(b + 1, vector<int>(n));
        for (int y = 1; y <= b; ++y)
            for (int j = n - 1; j >= 0; --j)
                dp[y][j] = (int)((nums[j] + (long)(j + y < n ? dp[y][j + y] : 0)) % MOD);
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            int x = q[0], y = q[1];
            if (y <= b) {
                ans.push_back(dp[y][x]);
            } else {
                long s = 0;
                for (int j = x; j < n; j += y) s += nums[j];
                ans.push_back((int)(s % MOD));
            }
        }
        return ans;
    }
};

