class Solution {
    public List<Integer> solve(List<Integer> nums, List<List<Integer>> queries) {
        final int MOD = 1_000_000_007;
        int n = nums.size();
        int b = (int) Math.sqrt(n) + 1;
        int[][] dp = new int[b + 1][n];
        for (int y = 1; y <= b; y++)
            for (int j = n - 1; j >= 0; j--)
                dp[y][j] = (nums.get(j) + (j + y < n ? dp[y][j + y] : 0)) % MOD;
        List<Integer> ans = new ArrayList<>();
        for (List<Integer> q : queries) {
            int x = q.get(0), y = q.get(1);
            if (y <= b) {
                ans.add(dp[y][x]);
            } else {
                long s = 0;
                for (int j = x; j < n; j += y) s += nums.get(j);
                ans.add((int) (s % MOD));
            }
        }
        return ans;
    }
}

